  ?artifact wdt:P1705 ?state ;
            wdt:P195 ?collection .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?country ?countryLabel ?isoCode ?nativeName WHERE {
  ?country wdt:P31 wd:Q6256 ;
           wdt:P30 wd:Q46 ;
           wdt:P297 ?isoCode ;
           wdt:P1705 ?nativeName .

  BIND(LCASE(?isoCode) AS ?isoLower)
  BIND(LCASE(?nativeName) AS ?nativeLower)

  FILTER(
    (STRSTARTS(?isoLower, SUBSTR(?isoLower, 1, 1)) && !CONTAINS(?nativeLower, SUBSTR(?isoLower, 1, 1))) ||
    (STRSTARTS(?isoLower, SUBSTR(?isoLower, 2, 1)) && !CONTAINS(?nativeLower, SUBSTR(?isoLower, 2, 1)))
  )

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

