           wdt:P625 ?coord1 .
  ?church2 wdt:P31 wd:Q16970 ;
           wdt:P17 wd:Q145 ;
           wdt:P625 ?coord2 .
  FILTER(?church1 < ?church2)
  SERVICE wikibase:around {
    ?church1 wdt:P625 ?coord1 .
    bd:serviceParam wikibase:center ?coord2 .
    bd:serviceParam wikibase:radius "0.1" .
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
LIMIT 100

SELECT ?praenomen ?praenomenLabel (COUNT(?person) AS ?count) WHERE {
  ?person wdt:P31 wd:Q5 ;
