  FILTER(REGEX(?name, "^(Aulus|Appius|Gaius|Gnaeus|Decimus|Kaeso|Lucius|Marcus|Manius|Numerius|Publius|Quintus|Servius|Sextus|Spurius|Titus|Tiberius)"))
  BIND(STRBEFORE(?name, " ") AS ?praenomen)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?praenomen ?praenomenLabel
ORDER BY DESC(?count)

