SELECT ?person ?personLabel ?start ?end (SUM(?duration) AS ?totalDuration) WHERE {
  ?person wdt:P39 wd:Q193582 ;
          p:P39 ?statement .
  ?statement ps:P39 wd:Q193582 ;
             pq:P580 ?start .
  OPTIONAL { ?statement pq:P582 ?end . }
  BIND(IF(BOUND(?end), ?end, NOW()) AS ?effectiveEnd)
  BIND(?effectiveEnd - ?start AS ?duration)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?person ?personLabel ?start ?end
ORDER BY DESC(?totalDuration)

