SELECT ?painting ?paintingLabel ?country ?countryLabel WHERE {
  ?painting wdt:P31 wd:Q3305213 ;
            wdt:P17 ?country .
  ?country wdt:P31 wd:Q6256 .
  {
    SELECT ?country (MAX(?sitelinks) AS ?maxSitelinks) WHERE {
      ?painting wdt:P31 wd:Q3305213 ;
                wdt:P17 ?country .
      ?painting wikibase:sitelinks ?sitelinks .
    } GROUP BY ?country
  }
  ?painting wikibase:sitelinks ?maxSitelinks .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?person ?personLabel WHERE {
  ?person wdt:P27 wd:Q258 ;
          wdt:P21 wd:Q6581072 .
  ?sitelink schema:about ?person ;
            schema:isPartOf <https://en.wikipedia.org/> .
  FILTER NOT EXISTS {
    ?qlink schema:about ?person ;
           schema:isPartOf <https://en.wikiquote.org/> .
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?place ?placeLabel ?coords WHERE {
  ?place wdt:P31/wdt:P279* wd:Q11424 .
  ?place wdt:P366 wd:Q175066 .
  ?place wdt:P625 ?coords .
  SERVICE wikibase:around {
    ?place wdt:P625 ?coords .
    bd:serviceParam wikibase:center "Point(0 0)"^^geo:wktLiteral .
    bd:serviceParam wikibase:radius "5" .
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?movie ?movieLabel ?youtubeLink WHERE {
  ?movie wdt:P31 wd:Q11424 ;
         wdt:P1651 ?youtubeLink .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?moon ?moonLabel ?namesake ?namesakeLabel WHERE {
  ?moon wdt:P31 wd:Q2634 ;
        wdt:P138 ?namesake .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?monument ?monumentLabel WHERE {
  ?monument wdt:P31/wdt:P279* wd:Q570116 .
  ?monument wdt:P138 ?person .
  FILTER NOT EXISTS {
    ?monument ?p ?o .
    FILTER(?p != wdt:P31 && ?p != wdt:P279 && ?p != wdt:P138 && ?p != wdt:P17 && ?p != wdt:P131)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?language ?languageLabel WHERE {
  wd:Q55 wdt:P37 ?language .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT DISTINCT ?party ?partyLabel WHERE {
  ?member wdt:P39 ?position .
  ?position wdt:P361 wd:Q17016666 .
  ?member p:P39 ?statement .
  ?statement ps:P39 ?position ;
             pq:P2715 wd:Q17016666 ;
             pq:P580 ?date .
  FILTER(YEAR(?date) = 1974 && MONTH(?date) = 2)
  ?member wdt:P102 ?party .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?language ?languageLabel ?followers ?date WHERE {
  ?language wdt:P31 wd:Q9143 ;
            p:P8687 ?statement .
  ?statement ps:P8687 ?followers ;
             pq:P585 ?date .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY DESC(?date)

SELECT ?language ?languageLabel ?code WHERE {
  ?language wdt:P31 wd:Q34770 ;
            wdt:P218 ?code .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT DISTINCT ?type ?typeLabel WHERE {
