        wdt:P31 ?type .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?astrolabe ?astrolabeLabel ?diameter ?inception WHERE {
  ?astrolabe wdt:P31 wd:Q193567.
  ?astrolabe wdt:P2386 ?diameter.
  ?astrolabe wdt:P571 ?inception.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?inception

SELECT ?letter ?letterLabel (COUNT(?alphabet) AS ?count) WHERE {
  ?alphabet wdt:P31 wd:Q820611 ;
            wdt:P282 ?letter .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
GROUP BY ?letter ?letterLabel
ORDER BY DESC(?count)

SELECT ?descendant ?descendantLabel WHERE {
  ?descendant wdt:P40* ?ancestor .
  ?ancestor wdt:P53* wd:Q193655 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?work ?workLabel ?date WHERE {
  ?work wdt:P50 wd:Q9068 ;
        wdt:P577 ?date .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?property ?propertyLabel ?date WHERE {
  wd:Q152236 ?p ?statement .
  ?statement a wikibase:BestRank ;
             ps:P569|ps:P570|ps:P585 ?date .
  ?property wikibase:claim ?p ;
            wikibase:label ?propertyLabel .
  FILTER(LANG(?propertyLabel) = "en")
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?date

SELECT ?property ?propertyLabel WHERE {
  ?property wdt:P31 wd:Q18616576 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?language ?languageLabel (COUNT(?film) AS ?count) WHERE {
  ?film wdt:P31 wd:Q11424 .
  ?sitelink schema:about ?film ;
            schema:isPartOf ?wiki .
  ?wiki wikibase:wikiGroup "wikipedia" ;
        wikibase:preferredLanguageCode ?langCode .
  BIND(IRI(CONCAT("http://www.wikidata.org/entity/", ?langCode)) AS ?language)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?language ?languageLabel
ORDER BY DESC(?count)
LIMIT 10

SELECT ?item ?itemLabel WHERE {
  ?item schema:about ?sitelink .
  ?sitelink schema:isPartOf <https://en.wikipedia.org/> ;
            schema:name ?name .
  FILTER(CONTAINS(?name, "University of Virginia"))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?city ?cityLabel ?population WHERE {
  ?city wdt:P31 wd:Q515 ;
        wdt:P17 wd:Q183 ;
        wdt:P1082 ?population .
  FILTER(?population > 50000)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?country ?countryLabel ?iso3166_1_alpha_2 ?flag ?fertilityRate WHERE {
  ?country wdt:P31 wd:Q6256 ;
           wdt:P297 ?iso3166_1_alpha_2 ;
           wdt:P41 ?flag ;
           wdt:P4841 ?fertilityRate .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?type ?typeLabel (COUNT(?work) AS ?count) WHERE {
  ?work wdt:P31 ?type .
  ?type wdt:P279* wd:Q7725634 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
GROUP BY ?type ?typeLabel
ORDER BY DESC(?count)

SELECT ?decade ?placeOfBirthLabel (COUNT(?person) AS ?count) WHERE {
  ?person wdt:P166 wd:Q37922 ;
          wdt:P19 ?placeOfBirth ;
          wdt:P569 ?birthDate .
  BIND(CONCAT(STR(FLOOR(YEAR(?birthDate) / 10) * 10), "s") AS ?decade)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
GROUP BY ?decade ?placeOfBirthLabel
ORDER BY ?decade ?placeOfBirthLabel
